    cursor: pointer;
    transition: all var(--transition-base);
    border: 1px solid var(--color-border);
    display: flex;
    flex-direction: column;
}

.product-card:hover, .product-card:focus-within {
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);
