        notification.style.animation = 'slideOut 0.3s ease-in-out';
        setTimeout(() => notification.remove(), 300);
    }, 2000);
}

// Add animation keyframes
const style = document.createElement('style');
style.textContent = `
    @keyframes slideIn {
        from {
            transform: translateX(400px);
            opacity: 0;
        }
        to {
            transform: translateX(0);
            opacity: 1;
        }
    }
    @keyframes slideOut {
        from {
            transform: translateX(0);
            opacity: 1;
        }
        to {
            transform: translateX(400px);
            opacity: 0;
        }
    }
`;
document.head.appendChild(style);

// Modal Management
const modal = document.getElementById('productModal');
const modalClose = document.querySelector('.modal-close');
const addToCartBtn = document.querySelector('.add-to-cart-btn');

function openModal(product) {
    document.getElementById('modalImage').src = product.image;
    document.getElementById('modalImage').alt = product.name;
    document.getElementById('modalTitle').textContent = product.name;
    document.getElementById('modalDescription').textContent = product.description || 'High-quality product for modern living';
    document.getElementById('modalPrice').textContent = `$${product.price.toFixed(2)}`;

    modal.classList.add('active');
    modal.setAttribute('aria-hidden', 'false');
    document.body.style.overflow = 'hidden';

    // Focus management
    modalClose.focus();
}

function closeModal() {
    modal.classList.remove('active');
    modal.setAttribute('aria-hidden', 'true');
    document.body.style.overflow = '';
}

// Modal Event Listeners
modalClose.addEventListener('click', closeModal);
addToCartBtn.addEventListener('click', addToCart);

modal.addEventListener('click', (e) => {
    if (e.target === modal) {
        closeModal();
    }
});

// Keyboard Navigation
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && modal.classList.contains('active')) {
        closeModal();
    }
});

// Render Products
function renderProducts() {
    const productsGrid = document.querySelector('.products-grid');
    productsGrid.innerHTML = productsData.map(product => `
        <li>
            <button 
                class="product-card" 
                aria-label="View details for ${product.name}"
                data-product-id="${product.id}"
            >
                <div class="product-image">${product.image}</div>
                <div class="product-info">
                    <h3 class="product-name">${product.name}</h3>
                    <p class="product-description">${product.description}</p>
                    <div class="product-price">$${product.price.toFixed(2)}</div>
                    <button class="product-btn" aria-label="Add ${product.name} to cart">
                        View Details
                    </button>
                </div>
            </button>
        </li>
    `).join('');

    // Add event listeners to product cards
    document.querySelectorAll('.product-card').forEach(card => {
        card.addEventListener('click', (e) => {
            e.preventDefault();
            const productId = card.dataset.productId;
            const product = productsData.find(p => p.id == productId);
            if (product) {
                openModal(product);
            }
        });
    });
}

// Render Deals
function renderDeals() {
    const dealsGrid = document.querySelector('.deals-grid');
    dealsGrid.innerHTML = dealsData.map(deal => `
        <li>
            <button 
                class="deal-card" 
                aria-label="View deal for ${deal.name} - Save ${deal.discount}%"
                data-deal-id="${deal.id}"
            >
                <div class="deal-badge">Save ${deal.discount}%</div>
                <div class="deal-image">${deal.image}</div>
                <div class="deal-info">
                    <h3 class="deal-name">${deal.name}</h3>
                    <div class="deal-prices">
                        <span class="deal-original">$${deal.originalPrice.toFixed(2)}</span>
                        <span class="deal-sale">$${deal.salePrice.toFixed(2)}</span>
                    </div>
                    <button class="deal-btn" aria-label="Add ${deal.name} to cart">
                        Claim Deal
                    </button>
                </div>
            </button>
        </li>
    `).join('');

    // Add event listeners to deal cards
    document.querySelectorAll('.deal-card').forEach(card => {
        card.addEventListener('click', (e) => {
            e.preventDefault();
            const dealId = card.dataset.dealId;
            const deal = dealsData.find(d => d.id == dealId);
            if (deal) {
                openModal({
                    id: deal.id,
                    name: deal.name,
                    description: `Limited time deal! Save ${deal.discount}% on this premium item.`,
                    price: deal.salePrice,
                    image: deal.image
                });
            }
        });
    });
}

// Render Articles
function renderArticles() {
    const articlesGrid = document.querySelector('.articles-grid');
    articlesGrid.innerHTML = articlesData.map(article => `
        <li>
            <article>
                <div class="article-image">${article.image}</div>
                <div class="article-category">${article.category}</div>
                <h3 class="article-title">${article.title}</h3>
                <p class="article-excerpt">${article.excerpt}</p>
                <a href="${article.url}" class="article-link" aria-label="Read ${article.title}">
                    Read Article →
                </a>
            </article>
        </li>
    `).join('');
}

// Newsletter Subscription
function setupNewsletterForm() {
    const form = document.querySelector('.newsletter-form');
    if (form) {
        form.addEventListener('submit', (e) => {
            e.preventDefault();
            const input = form.querySelector('input[type="email"]');
            if (input && input.value) {
                showNotification(`Newsletter subscription confirmed for ${input.value}!`);
                input.value = '';
            }
        });
    }
}

// Cart Button
function setupCartButton() {
    const cartBtn = document.querySelector('.cart-btn');
    if (cartBtn) {
        cartBtn.addEventListener('click', () => {
            showNotification(`Cart contains ${cartCount} items`);
        });
    }
}

// CTA Button
function setupCTAButton() {
    const ctaBtn = document.querySelector('.cta-btn');
    if (ctaBtn) {
        ctaBtn.addEventListener('click', () => {
            document.querySelector('#featured').scrollIntoView({ behavior: 'smooth' });
        });
    }
}

// Initialize page
function init() {
    renderProducts();
    renderDeals();
    renderArticles();
    setupNewsletterForm();
    setupCartButton();
    setupCTAButton();
    updateCartCount();

    // Smooth scrolling for navigation links
    document.querySelectorAll('a[href^="#"]').forEach(link => {
        link.addEventListener('click', (e) => {
            const href = link.getAttribute('href');
            if (href !== '#') {
                e.preventDefault();
                const target = document.querySelector(href);
                if (target) {
                    target.scrollIntoView({ behavior: 'smooth' });
                }
            }
        });
    });
}

// Run initialization when DOM is loaded
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
} else {
    init();
}
