/* Root Variables */
:root {
    --color-primary: #1a1a1a;
    --color-secondary: #ffffff;
    --color-accent: #2563eb;
    --color-accent-light: #dbeafe;
    --color-deal: #dc2626;
    --color-text: #374151;
    --color-text-light: #6b7280;
    --color-border: #e5e7eb;
    --color-bg-light: #f9fafb;
    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 1.5rem;
    --spacing-lg: 2rem;
    --spacing-xl: 3rem;
    --spacing-2xl: 4rem;
    --border-radius: 8px;
    --border-radius-lg: 12px;
    --transition-fast: 150ms ease-in-out;
    --transition-base: 250ms ease-in-out;
}

/* Reset and Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    color: var(--color-text);
    background-color: var(--color-secondary);
    line-height: 1.6;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
    color: var(--color-primary);
    font-weight: 600;
    line-height: 1.2;
}

h1 {
    font-size: 2rem;
}

h2 {
    font-size: 1.75rem;
    margin-bottom: var(--spacing-sm);
}

h3 {
    font-size: 1.25rem;
}

p {
    margin-bottom: var(--spacing-md);
}

a {
    color: var(--color-accent);
    text-decoration: none;
    transition: color var(--transition-fast);
}

a:hover, a:focus {
    color: #1d4ed8;
    outline: none;
}

button {
    font-family: inherit;
    cursor: pointer;
    border: none;
    transition: all var(--transition-fast);
}

/* Header */
.header {
    background-color: var(--color-primary);
    color: var(--color-secondary);
    padding: var(--spacing-md) 0;
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.header-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-lg);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo h1 {
    color: var(--color-secondary);
    font-size: 1.5rem;
}

.nav ul {
    display: flex;
    list-style: none;
    gap: var(--spacing-lg);
}

.nav a {
    color: var(--color-secondary);
    font-weight: 500;
    display: inline-block;
    padding: var(--spacing-xs) 0;
    border-bottom: 2px solid transparent;
    transition: border-color var(--transition-fast);
}

.nav a:hover, .nav a:focus {
    border-bottom-color: var(--color-accent);
}

.cart-btn {
    background-color: transparent;
    color: var(--color-secondary);
    font-size: 1.25rem;
    display: flex;
    align-items: center;
    gap: var(--spacing-xs);
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: var(--border-radius);
    border: 1px solid rgba(255, 255, 255, 0.2);
}

.cart-btn:hover, .cart-btn:focus {
    background-color: rgba(255, 255, 255, 0.1);
    border-color: rgba(255, 255, 255, 0.4);
}

.cart-count {
    background-color: var(--color-deal);
    color: var(--color-secondary);
    border-radius: 50%;
    width: 1.25rem;
    height: 1.25rem;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    font-weight: 700;
}

/* Hero Section */
.hero {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: var(--color-secondary);
    padding: var(--spacing-2xl) var(--spacing-lg);
    text-align: center;
    min-height: 400px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.hero-content h2 {
    color: var(--color-secondary);
    font-size: 2.5rem;
    margin-bottom: var(--spacing-md);
}

.hero-content p {
    font-size: 1.25rem;
    margin-bottom: var(--spacing-lg);
    opacity: 0.95;
}

.cta-btn {
    background-color: var(--color-accent);
    color: var(--color-secondary);
    padding: var(--spacing-sm) var(--spacing-xl);
    font-size: 1rem;
    font-weight: 600;
    border-radius: var(--border-radius-lg);
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.3);
}

.cta-btn:hover, .cta-btn:focus {
    background-color: #1d4ed8;
    box-shadow: 0 6px 16px rgba(37, 99, 235, 0.4);
    transform: translateY(-2px);
}

/* Section Container */
.section-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-lg);
}

/* Featured Products Section */
.featured {
    padding: var(--spacing-2xl) var(--spacing-lg);
    background-color: var(--color-secondary);
}

.featured h2 {
    color: var(--color-primary);
}

.section-subtitle {
    color: var(--color-text-light);
    font-size: 1.1rem;
    margin-bottom: var(--spacing-xl);
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
    gap: var(--spacing-lg);
    list-style: none;
}

.product-card {
    background-color: var(--color-bg-light);
    border-radius: var(--border-radius-lg);
    overflow: hidden;
    cursor: pointer;
    transition: all var(--transition-base);
    border: 1px solid var(--color-border);
    display: flex;
    flex-direction: column;
}

.product-card:hover, .product-card:focus-within {
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);
    transform: translateY(-4px);
}

.product-image {
    width: 100%;
    height: 250px;
    background-color: #f0f0f0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3rem;
    overflow: hidden;
    border-bottom: 1px solid var(--color-border);
}

.product-info {
    padding: var(--spacing-md);
    flex-grow: 1;
    display: flex;
    flex-direction: column;
}

.product-name {
    font-weight: 600;
    color: var(--color-primary);
    margin-bottom: var(--spacing-xs);
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.product-description {
    font-size: 0.9rem;
    color: var(--color-text-light);
    margin-bottom: var(--spacing-md);
    flex-grow: 1;
}

.product-price {
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--color-accent);
    margin-bottom: var(--spacing-md);
}

.product-btn {
    background-color: var(--color-primary);
    color: var(--color-secondary);
    padding: var(--spacing-sm) var(--spacing-md);
    border-radius: var(--border-radius);
    font-weight: 600;
    text-align: center;
    transition: background-color var(--transition-fast);
}

.product-btn:hover, .product-btn:focus {
    background-color: var(--color-accent);
}

/* Deals Section */
.deals {
    padding: var(--spacing-2xl) var(--spacing-lg);
    background-color: var(--color-bg-light);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: var(--spacing-lg);
    list-style: none;
}

.deal-card {
    background-color: var(--color-secondary);
    border-radius: var(--border-radius-lg);
    overflow: hidden;
    border: 2px solid var(--color-deal);
    cursor: pointer;
    transition: all var(--transition-base);
    display: flex;
    flex-direction: column;
}

.deal-card:hover, .deal-card:focus-within {
    box-shadow: 0 8px 24px rgba(220, 38, 38, 0.15);
    transform: translateY(-4px);
}

.deal-badge {
    background-color: var(--color-deal);
    color: var(--color-secondary);
    padding: var(--spacing-sm) var(--spacing-md);
    font-weight: 700;
    text-align: center;
    font-size: 1.1rem;
}

.deal-image {
    width: 100%;
    height: 250px;
    background-color: #f0f0f0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3rem;
    border-bottom: 1px solid var(--color-border);
}

.deal-info {
    padding: var(--spacing-md);
    flex-grow: 1;
    display: flex;
    flex-direction: column;
}

.deal-name {
    font-weight: 600;
    color: var(--color-primary);
    margin-bottom: var(--spacing-xs);
}

.deal-prices {
    display: flex;
    gap: var(--spacing-md);
    margin-bottom: var(--spacing-md);
    align-items: center;
}

.deal-original {
    text-decoration: line-through;
    color: var(--color-text-light);
    font-size: 0.95rem;
}

.deal-sale {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--color-deal);
}

.deal-btn {
    background-color: var(--color-deal);
    color: var(--color-secondary);
    padding: var(--spacing-sm) var(--spacing-md);
    border-radius: var(--border-radius);
    font-weight: 600;
    text-align: center;
}

.deal-btn:hover, .deal-btn:focus {
    background-color: #b91c1c;
}

/* Editorial Section */
.editorial {
    padding: var(--spacing-2xl) var(--spacing-lg);
    background-color: var(--color-secondary);
}

.articles-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: var(--spacing-xl);
    list-style: none;
}

.article-card {
    cursor: pointer;
    transition: all var(--transition-base);
    display: flex;
    flex-direction: column;
}

.article-card:hover, .article-card:focus-within {
    transform: translateY(-4px);
}

.article-image {
    width: 100%;
    height: 200px;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    border-radius: var(--border-radius-lg);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2.5rem;
    margin-bottom: var(--spacing-md);
    overflow: hidden;
}

.article-category {
    color: var(--color-accent);
    font-size: 0.85rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: var(--spacing-xs);
}

.article-title {
    font-size: 1.25rem;
    font-weight: 600;
    color: var(--color-primary);
    margin-bottom: var(--spacing-sm);
    line-height: 1.3;
}

.article-excerpt {
    color: var(--color-text-light);
    margin-bottom: var(--spacing-md);
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.article-link {
    color: var(--color-accent);
    font-weight: 600;
    display: inline-flex;
    align-items: center;
    gap: var(--spacing-xs);
}

.article-link:hover, .article-link:focus {
    gap: var(--spacing-sm);
}

/* Newsletter Section */
.newsletter {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: var(--color-secondary);
    padding: var(--spacing-2xl) var(--spacing-lg);
}

.newsletter-container {
    max-width: 600px;
    margin: 0 auto;
    text-align: center;
}

.newsletter-container h2 {
    color: var(--color-secondary);
    margin-bottom: var(--spacing-md);
}

.newsletter-container p {
    opacity: 0.95;
    margin-bottom: var(--spacing-lg);
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-sm);
}

.newsletter-form input {
    flex: 1;
    padding: var(--spacing-sm) var(--spacing-md);
    border: none;
    border-radius: var(--border-radius);
    font-size: 1rem;
}

.newsletter-form input::placeholder {
    color: #999;
}

.newsletter-form input:focus {
    outline: 2px solid var(--color-accent-light);
    outline-offset: 2px;
}

.newsletter-form button {
    background-color: var(--color-secondary);
    color: var(--color-primary);
    padding: var(--spacing-sm) var(--spacing-lg);
    border-radius: var(--border-radius);
    font-weight: 600;
}

.newsletter-form button:hover, .newsletter-form button:focus {
    background-color: var(--color-accent-light);
}

/* Footer */
.footer {
    background-color: var(--color-primary);
    color: var(--color-secondary);
    padding: var(--spacing-2xl) var(--spacing-lg) var(--spacing-lg);
}

.footer-container {
    max-width: 1200px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-xl);
    margin-bottom: var(--spacing-2xl);
}

.footer-section h3 {
    color: var(--color-secondary);
    margin-bottom: var(--spacing-md);
    font-size: 1rem;
}

.footer-section ul {
    list-style: none;
}

.footer-section li {
    margin-bottom: var(--spacing-sm);
}

.footer-section a {
    color: #d1d5db;
    transition: color var(--transition-fast);
}

.footer-section a:hover, .footer-section a:focus {
    color: var(--color-accent);
}

.social-links {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
}

.footer-bottom {
    max-width: 1200px;
    margin: 0 auto;
    padding-top: var(--spacing-lg);
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    text-align: center;
    color: #9ca3af;
    font-size: 0.9rem;
}

/* Modal */
.modal {
    display: none;
    position: fixed;
    z-index: 200;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(0, 0, 0, 0.5);
    align-items: center;
    justify-content: center;
}

.modal.active {
    display: flex;
}

.modal-content {
    background-color: var(--color-secondary);
    border-radius: var(--border-radius-lg);
    overflow: hidden;
    max-width: 600px;
    width: 90%;
    max-height: 90vh;
    overflow-y: auto;
    position: relative;
}

.modal-close {
    position: absolute;
    top: var(--spacing-md);
    right: var(--spacing-md);
    background-color: transparent;
    border: none;
    font-size: 2rem;
    color: var(--color-primary);
    z-index: 201;
    cursor: pointer;
    width: 2.5rem;
    height: 2.5rem;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: var(--border-radius);
}

.modal-close:hover, .modal-close:focus {
    background-color: var(--color-bg-light);
}

.modal-body {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-lg);
    padding: var(--spacing-lg);
}

.modal-image {
    width: 100%;
    height: 300px;
    object-fit: cover;
    border-radius: var(--border-radius);
    background-color: #f0f0f0;
}

.modal-info {
    display: flex;
    flex-direction: column;
}

.modal-info h3 {
    margin-bottom: var(--spacing-md);
}

.modal-price {
    margin: var(--spacing-md) 0;
}

.modal-price span {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--color-accent);
}

.add-to-cart-btn {
    background-color: var(--color-primary);
    color: var(--color-secondary);
    padding: var(--spacing-sm) var(--spacing-md);
    border-radius: var(--border-radius);
    font-weight: 600;
    font-size: 1rem;
    margin-top: auto;
    cursor: pointer;
}

.add-to-cart-btn:hover, .add-to-cart-btn:focus {
    background-color: var(--color-accent);
}

/* Responsive Design */
@media (max-width: 768px) {
    h1 {
        font-size: 1.5rem;
