.add-to-cart-btn:hover, .add-to-cart-btn:focus {
    background-color: var(--color-accent);
}

/* Responsive Design */
@media (max-width: 768px) {
    h1 {
        font-size: 1.5rem;
    }

    h2 {
        font-size: 1.5rem;
    }

    .header-container {
        padding: 0 var(--spacing-md);
    }

    .nav ul {
        gap: var(--spacing-md);
    }

    .nav {
        display: none;
    }

    .nav.active {
        display: block;
        position: absolute;
        top: 60px;
        left: 0;
        right: 0;
        background-color: var(--color-primary);
        padding: var(--spacing-lg);
    }

    .nav ul {
        flex-direction: column;
    }

    .hero-content h2 {
        font-size: 2rem;
    }

    .hero-content p {
        font-size: 1rem;
    }

    .featured,
    .deals,
    .editorial {
        padding: var(--spacing-xl) var(--spacing-md);
    }

    .products-grid,
    .deals-grid {
        grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
        gap: var(--spacing-md);
    }

    .articles-grid {
        grid-template-columns: 1fr;
        gap: var(--spacing-lg);
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input,
    .newsletter-form button {
        width: 100%;
    }

    .modal-body {
        grid-template-columns: 1fr;
        padding: var(--spacing-md);
    }

    .modal-image {
        height: 200px;
    }
}

@media (max-width: 480px) {
    :root {
        --spacing-lg: 1.5rem;
        --spacing-2xl: 2rem;
    }

    h1 {
        font-size: 1.25rem;
    }

    h2 {
        font-size: 1.25rem;
    }

    .products-grid,
    .deals-grid {
        grid-template-columns: 1fr;
    }

    .product-card,
    .deal-card {
        flex-direction: row;
    }

    .product-image,
    .deal-image {
        width: 100px;
        height: 100px;
        border-right: 1px solid var(--color-border);
        border-bottom: none;
    }

    .product-info,
    .deal-info {
        padding: var(--spacing-md);
    }

    .footer-container {
        grid-template-columns: 1fr;
        gap: var(--spacing-lg);
    }
}

/* Accessibility */
@media (prefers-reduced-motion: reduce) {
